class TinygradLlamaModel:
    """Tinygrad decode path, optionally backed by the KohakuTPU device.

    The first KTPU profile is multi-head attention (KV heads equal attention
    heads), 32-column-aligned dimensions, and a greedy vocabulary readback.
    """

    def __init__(
        self, config: LlamaConfig, weights: LlamaWeights, device: str = "KTPU"
    ) -> None:
        if device not in ("CPU", "KTPU"):
            raise ValueError("device must be CPU or KTPU")
        if config.kv_heads != config.num_attention_heads:
            raise ValueError(
                "the KTPU first profile requires num_key_value_heads == "
                "num_attention_heads"
            )
        if config.hidden_size % 32 or config.head_dim % 32:
            raise ValueError("KTPU LLaMA dimensions must use whole 32-column blocks")
        if config.intermediate_size % 32:
            raise ValueError("KTPU intermediate_size must use whole 32-column blocks")

        if device == "KTPU":
            # Register the backend before a Tensor is constructed for that device.
            import kohakutpu.application.ktpugrad  # noqa: F401
            from kohakutpu.application.runtime.device import device as runtime_device

            self._runtime = runtime_device()
        else:
            self._runtime = None

        try:
            from tinygrad.tensor import Tensor
        except ImportError as error:
            raise RuntimeError(
                "install tinygrad with `uv sync --project software/application "
                "--extra ktpugrad`"
            ) from error

        self.config, self.device, self.Tensor = config, device, Tensor
        self.last_profile = None
        self._np_dtype = np.float16 if device == "KTPU" else np.float32
        _trace_memory("weights: start")
        self._embed = np.asarray(weights.embed_tokens)
        self._rope_inv_freq = config.rope_theta ** (
            -np.arange(0, config.head_dim, 2, dtype=np.float32) / config.head_dim
        )
        self._vocab_pad = (-config.vocab_size) % 32
        head = weights.embed_tokens if weights.lm_head is None else weights.lm_head
        if self._vocab_pad:
            padded = np.zeros(
                (config.vocab_size + self._vocab_pad, config.hidden_size),
                dtype=np.asarray(head).dtype,
            )
            padded[: config.vocab_size] = head
            head = padded

        def place(array):
            return Tensor(
                np.ascontiguousarray(np.asarray(array, dtype=self._np_dtype)),
                device=device,
            )

"""Load a local Hugging Face LLaMA checkpoint using optional safe-tensor support."""

from __future__ import annotations

import json
import pathlib

from kohakutpu.application.llm.llama import (
    LlamaConfig,
    LlamaModel,
    weights_from_huggingface,
)


def load_model(directory: str | pathlib.Path) -> tuple[LlamaConfig, LlamaModel]:
    """Load ``config.json`` and a single-file ``model.safetensors`` directory."""
    root = pathlib.Path(directory)
    config_path = root / "config.json"
    weights_path = root / "model.safetensors"
    if not config_path.is_file():
        raise FileNotFoundError(config_path)
    if not weights_path.is_file():
        raise FileNotFoundError(
            f"{weights_path} is required; this loader expects a single-file "
            "model.safetensors checkpoint"
        )
    try:
        from safetensors.numpy import load_file
    except ImportError as error:
        raise RuntimeError(
            "install the optional LLM dependencies with "
            "`uv sync --project software/application --extra llm`"
        ) from error

    values = json.loads(config_path.read_text())
    config = LlamaConfig.from_huggingface(values)
    state = load_file(str(weights_path))
    weights = weights_from_huggingface(config, state)
    return config, LlamaModel(config, weights)

